    def read_ints():
        return list(map(int, sys.stdin.readline().strip().split()))

    n, m = read_ints()
    a = read_ints()

    from sortedcontainers import SortedList

    freq = [SortedList() for _ in range(100001)]
    count = [0] * (n + 1)

    def add(x, pos):
        if count[pos] > 0:
            freq[count[pos]].remove(pos)
        count[pos] = x
        if x > 0:
            freq[x].add(pos)

    def remove(pos):
        x = count[pos]
        if x > 0:
            freq[x].remove(pos)
        count[pos] = 0

    for i in range(n):
        add(a[i], i + 1)

    def query(l, r, k):
        min_dif = float('inf')
        for f in range(1, 100001):
            if len(freq[f]) < k:
                continue
            indices = []
            for i in range(k):
                idx = bisect.bisect_left(freq[f], l - 1)
                if idx >= len(freq[f]) or freq[f][idx] > r:
                    break
                indices.append(freq[f][idx])
                freq[f].pop(idx)
            if len(indices) == k:
                min_val = min(count[i] for i in indices)
                max_val = max(count[i] for i in indices)
                min_dif = min(min_dif, max_val - min_val)
            for i in indices:
                freq[count[i]].add(i)
            if min_dif == 0:
                break
        return min_dif if min_dif != float('inf') else -1

    results = []
    for _ in range(m):
        q = read_ints()
        if q[0] == 1:
            l, r, k = q[1], q[2], q[3]
